async function mapLimit(items, limit, worker) {
  const queue = [...items];
  return Promise.all(Array.from({ length: limit }, async () => {
    const out = [];
    while (queue.length) out.push(await worker(queue.shift()));
    return out;
  })).then(parts => parts.flat());
}

