  const request = mock.fn(async () => request.mock.callCount() === 1 ? Promise.reject(new Error('busy')) : 'ok');
  const result = await retry(request, { attempts: 2, delay: 0 });
  assert.equal(result, 'ok');
  assert.equal(request.mock.callCount(), 2);
});

